Aktiv.onCheckChange:
{{
  (async () => {
    // 1. Auslösende Zeile und Haus-Wert ermitteln (linter-sicher)
    const row = (typeof Table2Copy !== 'undefined' ? Table2Copy.triggeredRow : null) || 
                (typeof Table2 !== 'undefined' ? Table2.updatedRow : null) || {};

    const hausNummerRaw = row.Haus ?? row.haus ?? row.Haus_Aktiv ?? "";
    const hausNummer = String(hausNummerRaw).trim();

    // Neuer Status
    const neuerStatus = row?.Aktiv ?? false;
    const statusString = neuerStatus ? "TRUE" : "FALSE";

    if (!hausNummer) {
      showAlert("Fehler: Konnte 'Haus' aus der Tabellenzeile nicht lesen.", "error");
      return;
    }

    const stammdatenArray = Stammdaten.data || [];

    // 2. Zeilen in den Stammdaten suchen (Vergleich ohne führende Nullen / Leerzeichen)
    const matchingRows = [];
    stammdatenArray.forEach((r, idx) => {
      const sheetHaus = String(r.Haus || "").trim();
      if (sheetHaus === hausNummer) {
        matchingRows.push(idx + 2);
      }
    });

    if (matchingRows.length === 0) {
      showAlert(`Keine Zeilen für Haus '${hausNummer}' in Stammdaten gefunden!`, "error");
      return;
    }

    // 3. Alle gefundenen Zeilen nacheinander in Google Sheets aktualisieren
    for (const sheetRowIndex of matchingRows) {
      await Update_Haus_Aktiv.run({
        rowIndex: sheetRowIndex,
        neuerStatus: statusString
      });
    }

    // 4. Stammdaten neu laden
    await Stammdaten.run();
    showAlert(`Haus ${hausNummer} auf ${statusString} gesetzt (${matchingRows.length} Zeilen aktualisiert).`, "success");
  })()
}}

tableData:
{{ 
  [...new Set(Stammdaten.data.map(item => item.Haus))].map(h => {
    const eintrag = Stammdaten.data.find(item => item.Haus === h);
    return {
      Haus: "Haus " + h,
      Haus_ID: h,
      Aktiv: eintrag ? (eintrag.Haus_Aktiv === true || String(eintrag.Haus_Aktiv).toUpperCase() === "JA" || eintrag.Haus_Aktiv === 1) : false
    };
  })
}}
